import sys

def main():
    import sys
    n = int(sys.stdin.read().strip())
    if n == 2:
        print("-1")
        print("1 2")
    else:
        # Incorrect tree for Mahmoud's algorithm
        for i in range(2, n // 2 + 2):
            print(f"1 {i}")
        for i in range(n // 2 + 2, n):
            print(f"{n // 2 + 1} {i}")
        # Correct tree for Mahmoud's algorithm
        print()
        for i in range(2, n + 1):
            print(f"1 {i}")

main()
